bnr.css:
#ksBnr .dnw{position:relative;flex:none;width:390px;height:160px;overflow:hidden;background:#E9DDB2}
#ksBnr .dnw>*{position:absolute;display:block}
#ksBnr .dnw .bnr{left:0;top:0;width:390px;height:160px;object-fit:cover}
#ksBnr .dnw .dnSky{left:0;top:0;width:390px;height:160px}
#ksBnr .dnw .dnGl{left:54px;top:10px;width:60px;height:40px;animation:kbdnGlow 3.8s ease-in-out infinite;will-change:opacity}
#ksBnr .dnw .dnPf{left:0;top:0;width:40px;height:32px;opacity:0;will-change:transform,opacity}
#ksBnr .dnw .dnPt{left:0;top:0;width:40px;height:20px;will-change:transform}
#ksBnr .dnw .dnPt>img{position:absolute;left:0;top:0;width:40px;height:20px}
#ksBnr .dnw .dnPw{transform-origin:15px 10px;animation:kbdnFlap .7s ease-in-out infinite alternate}
#ksBnr .dnw .dnMd{left:0;top:66px;width:782px;height:60px;background-size:390px 60px;background-repeat:repeat-x;animation:kbdnMid 9.0s linear infinite}
#ksBnr .dnw .dnSa{left:232px;top:0px;width:168px;height:120px;animation:kbdnBob 1.3s ease-in-out infinite}
#ksBnr .dnw .dnSa>img{position:absolute;left:0;top:0;width:168px;height:120px}
#ksBnr .dnw .dnGd{left:0;top:116px;width:782px;height:44px;background-size:390px 44px;background-repeat:repeat-x;animation:kbdnGround 2.5s linear infinite}
#ksBnr .dnw .dnS.legFN{transform-origin:60px 78px;animation:kbdnLeg 2.6s ease-in-out 0s infinite}
#ksBnr .dnw .dnS.legHF{transform-origin:118px 78px;animation:kbdnLeg 2.6s ease-in-out 0s infinite}
#ksBnr .dnw .dnS.legFF{transform-origin:68px 78px;animation:kbdnLeg 2.6s ease-in-out -1.3s infinite}
#ksBnr .dnw .dnS.legHN{transform-origin:110px 78px;animation:kbdnLeg 2.6s ease-in-out -1.3s infinite}
#ksBnr .dnw .dnS.neck{transform-origin:66px 70px;animation:kbdnNeck 5.2s ease-in-out infinite}
#ksBnr .dnw .dnS.tail{transform-origin:120px 66px;animation:kbdnTail 3.4s ease-in-out infinite}
#ksBnr .dnw .dnH.h1{left:71px;top:41px;width:160px;height:110px;overflow:hidden}
#ksBnr .dnw .dnH.h1>i{display:block;width:1600px;height:110px;background:url(ks_3bfa46d69b4fc9b8f1d51798c088b429.webp) 0 0/1600px 110px no-repeat;animation:kbdnRun1 0.5s steps(10) 0s infinite}
@keyframes kbdnRun1{100%{transform:translateX(-1600px)}}
#ksBnr .dnw .dnSd.s1{left:109.4px;top:142px;width:89.6px;height:8px;border-radius:50%;background:radial-gradient(closest-side,rgba(80,50,20,.45),rgba(80,50,20,0))}
#ksBnr .dnw .dnH.h2{left:162px;top:26px;width:136px;height:93px;overflow:hidden}
#ksBnr .dnw .dnH.h2>i{display:block;width:1360px;height:93px;background:url(ks_e57301ecb3195876110e0595dd38b037.webp) 0 0/1360px 93px no-repeat;animation:kbdnRun2 0.5s steps(10) -0.17s infinite}
@keyframes kbdnRun2{100%{transform:translateX(-1360px)}}
#ksBnr .dnw .dnSd.s2{left:194.64px;top:112px;width:76.16px;height:8px;border-radius:50%;background:radial-gradient(closest-side,rgba(80,50,20,.45),rgba(80,50,20,0))}
#ksBnr .dnw .dnRx{left:0;top:94px;width:60px;height:46px;animation:kbdnRace 16s linear infinite;will-change:transform}
#ksBnr .dnw .dnRx>img{position:absolute;left:0;top:0;width:60px;height:46px}
#ksBnr .dnw .dnR.body{animation:kbdnRBob .16s ease-in-out infinite alternate}
#ksBnr .dnw .dnR.legN{transform-origin:29px 25px;animation:kbdnRLeg .32s linear infinite}
#ksBnr .dnw .dnR.legF{transform-origin:29px 25px;animation:kbdnRLeg .32s linear -.16s infinite}
@keyframes kbdnRace{0%{transform:translate(-70px,0)}4%{transform:translate(-70px,0)}34%{transform:translate(420px,-3px)}100%{transform:translate(420px,-3px)}}
@keyframes kbdnRBob{0%{transform:translateY(0)}100%{transform:translateY(-1.6px)}}
@keyframes kbdnRLeg{0%{transform:rotate(-34deg)}50%{transform:rotate(30deg)}100%{transform:rotate(-34deg)}}
#ksBnr .dnw .dnPf.p0{animation:kbdnPuff 6s ease-out 0s infinite}
#ksBnr .dnw .dnPf.p1{animation:kbdnPuff 6s ease-out -1s infinite}
#ksBnr .dnw .dnPf.p2{animation:kbdnPuff 6s ease-out -2s infinite}
#ksBnr .dnw .dnPf.p3{animation:kbdnPuff 6s ease-out -3s infinite}
#ksBnr .dnw .dnPf.p4{animation:kbdnPuff 6s ease-out -4s infinite}
#ksBnr .dnw .dnPf.p5{animation:kbdnPuff 6s ease-out -5s infinite}
@keyframes kbdnPuff{0%{opacity:0;transform:translate(64px,16px) scale(.35)}10%{opacity:.85;transform:translate(66px,6px) scale(.55)}60%{opacity:.6;transform:translate(88px,-20px) scale(1.1)}100%{opacity:0;transform:translate(114px,-42px) scale(1.6)}}
#ksBnr .dnw .dnPt.q0{animation:kbdnFly0 14.0s linear 0.0s infinite}
@keyframes kbdnFly0{0%{transform:translate(410px,26px) scale(1.0)}50%{transform:translate(190px,14px) scale(1.0)}100%{transform:translate(-60px,14px) scale(1.0)}}
#ksBnr .dnw .dnPt.q1{animation:kbdnFly1 18.0s linear -7.0s infinite}
@keyframes kbdnFly1{0%{transform:translate(410px,44px) scale(0.75)}50%{transform:translate(190px,33px) scale(0.75)}100%{transform:translate(-60px,34px) scale(0.75)}}
@keyframes kbdnGlow{0%{opacity:.55;transform:scale(.92)}50%{opacity:.95;transform:scale(1.06)}100%{opacity:.55;transform:scale(.92)}}
@keyframes kbdnFlap{0%{transform:scaleY(1)}100%{transform:scaleY(-.55)}}
@keyframes kbdnMid{0%{transform:translateX(0)}100%{transform:translateX(-390px)}}
@keyframes kbdnGround{0%{transform:translateX(0)}100%{transform:translateX(-390px)}}
@keyframes kbdnBob{0%{transform:translateY(0)}50%{transform:translateY(1.2px)}100%{transform:translateY(0)}}
@keyframes kbdnLeg{0%{transform:rotate(-11deg)}50%{transform:rotate(11deg)}100%{transform:rotate(-11deg)}}
@keyframes kbdnNeck{0%{transform:rotate(-2.5deg)}50%{transform:rotate(3.5deg)}100%{transform:rotate(-2.5deg)}}
@keyframes kbdnTail{0%{transform:rotate(-5deg)}50%{transform:rotate(5deg)}100%{transform:rotate(-5deg)}}
@media (prefers-reduced-motion:reduce){#ksBnr .dnw .dnSky,#ksBnr .dnw .dnGl,#ksBnr .dnw .dnPf,#ksBnr .dnw .dnPt,#ksBnr .dnw .dnMd,#ksBnr .dnw .dnSa,#ksBnr .dnw .dnGd,#ksBnr .dnw .dnSd,#ksBnr .dnw .dnH,#ksBnr .dnw .dnRx{display:none!important}}
/* 設定の「演出を控えめにする」＝視差効果を減らすと同じ形（16.6） */
#ksBnr.calm .dnw .dnSky,#ksBnr.calm .dnw .dnGl,#ksBnr.calm .dnw .dnPf,#ksBnr.calm .dnw .dnPt,#ksBnr.calm .dnw .dnMd,#ksBnr.calm .dnw .dnSa,#ksBnr.calm .dnw .dnGd,#ksBnr.calm .dnw .dnSd,#ksBnr.calm .dnw .dnH,#ksBnr.calm .dnw .dnRx{display:none!important}

push.css:
.fxs .dn{--pushA:#3A2E36;--pushB:#1A1418;--pushC:#5A4A50;--rim:#FF8A3A;--rimD:#241C22}
.fxs .push.dn{--pr:40px;background:none;border-radius:40px;box-shadow:none;filter:drop-shadow(0 8px 0 rgba(30,20,10,.5)) drop-shadow(0 18px 24px rgba(0,0,0,.4))}
.fxs .push.dn span{top:2px;font:400 42px/1 "Yuji Boku",serif;letter-spacing:.06em;color:#FFC15A;text-shadow:0 3px 0 #7A2A0E,0 0 12px rgba(255,138,58,.65)}
.fxs .push.dn::after{inset:-24px;top:-46px;border-radius:60px;border-color:rgba(255,160,80,.9)}
.fxs .dn .dnf{position:absolute;left:-30px;top:-36px;width:260px;height:150px;pointer-events:none;font-style:normal}
.fxs .dn .dnf svg{display:block;width:260px;height:150px;overflow:visible}
.fxs .dn .dnd{position:absolute;left:-40px;top:-70px;width:280px;height:190px;pointer-events:none;z-index:3;font-style:normal}
.fxs .dn .dnd svg{display:block;width:280px;height:190px;overflow:visible}
.fxs .dn .dnlv{animation:fxdnLv 3.2s ease-in-out infinite}
@keyframes fxdnLv{0%,100%{opacity:.6}50%{opacity:1}}
.fxs .dn .dnem{animation:fxdnEm 2.7s ease-out infinite}
@keyframes fxdnEm{0%{opacity:0;transform:translateY(0)}20%{opacity:.95}100%{opacity:0;transform:translateY(-46px)}}
.fxs .dn .dnpt{animation:fxdnPtB 2.4s ease-in-out infinite alternate}
