.fxs .pshadow.dn{width:230px}
.fxs .tap.dn{font-family:"Yuji Boku",serif;font-weight:400;color:#FFC15A;letter-spacing:.12em;text-shadow:0 2px 0 #2C4220,0 0 10px rgba(255,138,58,.6)}
.fxs .pressed.dn{border-radius:40px;background:#3A2E36;box-shadow:0 0 0 4px #FF8A3A,0 7px 0 4px #241C22;animation-name:fxdnPress,fxfxH}
@keyframes fxdnPress{0%{transform:scale(1)}22%{transform:scale(.9,.84)}45%{transform:scale(1.07)}100%{transform:scale(1.45);opacity:0}}
@media (prefers-reduced-motion:reduce){.fxs .dn .dnlv,.fxs .dn .dnem,.fxs .dn .dnpt{animation:none}
.fxs .dn .dnem,.fxs .clips.dn{display:none}}
.fxs .clips.dn{position:absolute;z-index:4;left:50%;top:calc(50% - 40px);width:0;height:0}
